import React, { useState, useEffect } from "react";
import axiosClient from "../../utils/axiosConfig"; // Sử dụng axiosClient đã cấu hình sẵn cổng 4000
import {
  FaMapMarkerAlt,
  FaPhone,
  FaTruck,
  FaClock,
  FaUser,
} from "react-icons/fa";

const styles = {
  shippingInfoBox: {
    padding: "20px",
    border: "1px solid #ddd",
    borderRadius: "8px",
    backgroundColor: "#f9f9f9",
    marginBottom: "30px",
  },
  shippingInfoTitle: {
    fontSize: "1.2em",
    fontWeight: "bold",
    color: "#333",
    marginBottom: "15px",
    borderBottom: "1px solid #eee",
    paddingBottom: "10px",
    display: "flex",
    alignItems: "center",
    gap: "10px",
  },
  detailItem: {
    display: "flex",
    alignItems: "flex-start",
    gap: "12px",
    marginBottom: "12px",
  },
  icon: { color: "#c90000", marginTop: "4px" },
  label: { fontSize: "0.85em", color: "#777", margin: 0 },
  value: { fontSize: "1em", fontWeight: "600", color: "#333", margin: 0 },
};

const ShippingInformation = ({ orderId }) => {
  const [shippingData, setShippingData] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchShippingInfo = async () => {
      if (!orderId) return;
      setIsLoading(true);
      setError(null);
      try {
        const response = await axiosClient.get(
          `/orders/${orderId}/shipping-info`
        );
        setShippingData(response.data);
      } catch (err) {
        console.error("Lỗi khi tải thông tin vận chuyển:", err);
        setError("Không thể tải thông tin vận chuyển vào lúc này.");
      } finally {
        setIsLoading(false);
      }
    };

    fetchShippingInfo();
  }, [orderId]);

  if (!orderId)
    return <p style={{ color: "red" }}>Lỗi: Không tìm thấy mã đơn hàng.</p>;
  if (isLoading) return <p>Đang tải thông tin vận chuyển...</p>;
  if (error) return <p style={{ color: "red" }}>{error}</p>;
  if (!shippingData)
    return <p>Chưa có thông tin vận chuyển cho đơn hàng này.</p>;

  return (
    <div style={styles.shippingInfoBox}>
      <h3 style={styles.shippingInfoTitle}>
        <FaTruck /> Thông tin Vận chuyển
      </h3>

      <div
        style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px" }}
      >
        {/* Cột 1: Thông tin người nhận */}
        <div>
          <p
            style={{
              fontWeight: "bold",
              marginBottom: "10px",
              fontSize: "0.9em",
              color: "#c90000",
            }}
          >
            NGƯỜI NHẬN
          </p>
          <div style={styles.detailItem}>
            <FaUser style={styles.icon} />
            <div>
              <p style={styles.label}>Họ tên:</p>
              <p style={styles.value}>{shippingData.recipientName}</p>
            </div>
          </div>
          <div style={styles.detailItem}>
            <FaPhone style={styles.icon} />
            <div>
              <p style={styles.label}>Số điện thoại:</p>
              <p style={styles.value}>{shippingData.phone}</p>
            </div>
          </div>
          <div style={styles.detailItem}>
            <FaMapMarkerAlt style={styles.icon} />
            <div>
              <p style={styles.label}>Địa chỉ giao hàng:</p>
              <p style={styles.value}>{shippingData.address}</p>
            </div>
          </div>
        </div>

        {/* Cột 2: Thông tin Shipper (Nếu đã có người nhận đơn) */}
        <div>
          <p
            style={{
              fontWeight: "bold",
              marginBottom: "10px",
              fontSize: "0.9em",
              color: "#c90000",
            }}
          >
            ĐƠN VỊ VẬN CHUYỂN
          </p>
          {shippingData.shipperName ? (
            <>
              <div style={styles.detailItem}>
                <FaTruck style={styles.icon} />
                <div>
                  <p style={styles.label}>Shipper:</p>
                  <p style={styles.value}>{shippingData.shipperName}</p>
                </div>
              </div>
              <div style={styles.detailItem}>
                <FaPhone style={styles.icon} />
                <div>
                  <p style={styles.label}>SĐT Shipper:</p>
                  <p style={styles.value}>
                    {shippingData.shipperPhone || "Đang cập nhật"}
                  </p>
                </div>
              </div>
              <div style={styles.detailItem}>
                <FaClock style={styles.icon} />
                <div>
                  <p style={styles.label}>Trạng thái:</p>
                  <p style={{ ...styles.value, color: "#00bcd4" }}>
                    Đang giao hàng
                  </p>
                </div>
              </div>
            </>
          ) : (
            <p style={{ fontStyle: "italic", color: "#999" }}>
              Đang chờ tìm Shipper phù hợp...
            </p>
          )}
        </div>
      </div>
    </div>
  );
};

export default ShippingInformation;
